// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 deposit, uint256 withdrawAmount) public {
        // Ensure caller is not address(0) to avoid issues
        vm.assume(caller != address(0));
        // Bound values to reasonable ranges
        deposit = bound(deposit, 0, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, 100 ether);

        // Fund the caller and give ETH to the contract
        vm.deal(caller, deposit + 10 ether);
        vm.deal(address(c), 100 ether);

        // Deposit if msg.value >= MinDeposit (MinDeposit = 1 ether)
        if (deposit >= c.MinDeposit()) {
            vm.prank(caller);
            c.Deposit{value: deposit}();
        }

        uint256 callerBalanceBefore = c.balances(caller);
        uint256 callerEthBefore = caller.balance;

        // Perform CashOut
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        uint256 callerBalanceAfter = c.balances(caller);
        uint256 callerEthAfter = caller.balance;

        // Generalized invariant:
        // If the caller had enough balance, the balance decreases by exactly withdrawAmount and caller gets ETH.
        // Otherwise, nothing changes.
        if (withdrawAmount <= callerBalanceBefore) {
            // In the reference, this succeeds; in the mutant, withdrawAmount == callerBalanceBefore fails (since condition is >) 
            assertTrue(
                (success && callerBalanceAfter == callerBalanceBefore - withdrawAmount && callerEthAfter == callerEthBefore + withdrawAmount) ||
                (!success && callerBalanceAfter == callerBalanceBefore && callerEthAfter == callerEthBefore)
            );
        } else {
            assertTrue(callerBalanceAfter == callerBalanceBefore && callerEthAfter == callerEthBefore);
        }
    }
}

