import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);

        // Fund the contract
        vm.deal(address(c), 1000 ether);

        // Set up caller's balance in the contract
        vm.startPrank(caller);
        // Simulate previous deposit: directly set balance via deposit
        // But deposit requires msg.value >= MinDeposit (1 ether), so we craft a deposit
        vm.deal(caller, 1 ether);
        c.Deposit{value: 1 ether}();
        vm.stopPrank();

        // Now caller has 1 ether balance. Let's capture pre-state
        uint256 preBalance = c.balances(caller);
        uint256 preContractBalance = address(c).balance;

        // Call CashOut with amount <= preBalance
        vm.assume(amount <= preBalance);

        vm.prank(caller);
        c.CashOut(amount);

        uint256 postBalance = c.balances(caller);
        uint256 postContractBalance = address(c).balance;

        // General rule: balance decreases exactly by amount, and contract balance decreases exactly by amount
        assertTrue(postBalance == preBalance - amount && postContractBalance == preContractBalance - amount, "Property failed");
    }
}

