        (bool success,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, cashOutAmt));

        if (success) {
            // After CashOut, the invariant: contract balance equals sum of all user balances (from public getter)
            uint256 totalUserBalances = 0;
            // We cannot iterate all users, so we check the specific user's balance change
            uint256 newUserBalance = c.balances(user);
            uint256 expectedNewBalance = userBalanceBefore - cashOutAmt;
            assertTrue(newUserBalance == expectedNewBalance, "User balance after CashOut incorrect");
        }
